int uniquePaths(int m, int n) {
  long long dp[100];
  for (int j = 0; j < n; j++) dp[j] = 1;
  for (int i = 1; i < m; i++) {
    for (int j = 1; j < n; j++) {
      dp[j] += dp[j - 1];
    }
  }
  return (int)dp[n - 1];
}

class Solution {
public:
  int uniquePaths(int m, int n) {
    vector<long long> dp(n, 1);
    for (int i = 1; i < m; i++) {
      for (int j = 1; j < n; j++) {
        dp[j] += dp[j - 1];
      }
    }
    return (int)dp[n - 1];
  }
};

func uniquePaths(m int, n int) int {
	dp := make([]int, n)
	for j := range dp {
		dp[j] = 1
	}
	for i := 1; i < m; i++ {
		for j := 1; j < n; j++ {
			dp[j] += dp[j-1]
		}
	}
	return dp[n-1]
}

class Solution {
  public int uniquePaths(int m, int n) {
    long[] dp = new long[n];
    java.util.Arrays.fill(dp, 1);
    for (int i = 1; i < m; i++) {
      for (int j = 1; j < n; j++) {
        dp[j] += dp[j - 1];
      }
    }
    return (int) dp[n - 1];
  }
}

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        dp = [1] * n
        for _ in range(1, m):
            for j in range(1, n):
                dp[j] += dp[j - 1]
        return dp[n - 1]

impl Solution {
  pub fn unique_paths(m: i32, n: i32) -> i32 {
    let n = n as usize;
    let mut dp = vec![1i64; n];
    for _ in 1..m {
      for j in 1..n {
        dp[j] += dp[j - 1];
      }
    }
    dp[n - 1] as i32
  }
}

const uniquePaths = (m: number, n: number): number => {
  const dp: number[] = new Array(n).fill(1);
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) dp[j] += dp[j - 1];
  }
  return dp[n - 1];
};
